head.script:
scwin.screenId = "jldfil71504";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '3'); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='3'); } }, { id: "btn_DigitalSub", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='4' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "if_corpUsrTpCd", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='1E'); } }, { id: "tr_64", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='1E'); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='1D'); } }, { id: "tr_75", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='1D'); } }, { id: "tr_85", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) ==='1D'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.insertComma(3);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71504.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71504.onpageload' });
    }
};


